scripts.host.probe:
{
  "schema": 1,
  "timeout_ms": 900000,
  "step_timeout_ms": 60000,
  "label_dump": {
    "every_ms": 5000
  },
  "steps": [
    {
      "op": "wait",
      "editing": true
    },
    {
      "op": "assert_relay"
    },
    {
      "op": "editor_pick",
      "input_player": 0
    },
    {
      "op": "editor_move",
      "input_player": 0,
      "x_fraction": 0.35
    },
    {
      "op": "wait",
      "renders": 5,
      "elapsed_ms": 1000
    },
    {
      "op": "menu",
      "command": "video_mark valid-preview-host",
      "capture_screen": "game"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "valid-preview-host",
      "scope": "menu"
    },
    {
      "op": "assert_editor",
      "input_player": 0,
      "equals": {
        "screen_text": "Valid spot - click to INSTALL your brain"
      }
    },
    {
      "op": "assert_net_ui_clear",
      "player": 0
    },
    {
      "op": "assert_control",
      "control": "LabelNetMatchStatus",
      "text_contains": "0 of 2",
      "fits": true,
      "inside": "BoxNetMatchStatus"
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": true
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": false
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "setup_ready": 1
    },
    {
      "op": "menu",
      "command": "video_mark placed-host",
      "capture_screen": "game"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "placed-host",
      "scope": "menu"
    },
    {
      "op": "assert_editor",
      "input_player": 0,
      "equals": {
        "ready": true,
        "submitted": true,
        "screen_text": "READY to start - wait for others to finish..."
      }
    },
    {
      "op": "assert_net_ui_clear",
      "player": 0
    },
    {
      "op": "assert_control",
      "control": "LabelNetMatchStatus",
      "text_contains": "1 of 2",
      "fits": true,
      "inside": "BoxNetMatchStatus"
    },
    {
      "op": "key_down",
      "key": "Return"
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "key_up",
      "key": "Return"
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "editing": false,
      "paused": false
    },
    {
      "op": "assert",
      "equals": {
        "setup_ready": 2,
        "setup_humans": 2,
        "local_actor_alive": true
      }
    },
    {
      "op": "assert_scene",
      "input_player": 0,
      "equals": {
        "alive": true,
        "brain_count": 2
      }
    },
    {
      "op": "menu",
      "command": "video_mark playing-host",
      "capture_screen": "game"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "playing-host",
      "scope": "menu"
    },
    {
      "op": "key_down",
      "key": "F6"
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "key_up",
      "key": "F6"
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "panel_open": true
    },
    {
      "op": "wait",
      "held_peer": "Leaver",
      "within_ms": 90000
    },
    {
      "op": "menu",
      "command": "video_mark leaver-held-host",
      "capture_screen": "game"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "leaver-held-host",
      "scope": "menu"
    },
    {
      "op": "assert_control",
      "control": "NetworkSeatDetail@Leaver",
      "text_contains": "Left ",
      "fits": true,
      "inside": "NetworkSeats"
    },
    {
      "op": "wait",
      "control": "NetworkSeatApplicant@Leaver",
      "text_contains": "Newcomer",
      "equals": {
        "visible": true
      },
      "within_ms": 180000
    },
    {
      "op": "menu",
      "command": "video_mark newcomer-asks-host",
      "capture_screen": "game"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "newcomer-asks-host",
      "scope": "menu"
    },
    {
      "op": "mouse_down",
      "control": "NetworkSeatDeclineApplicant@Leaver"
    },
    {
      "op": "wait",
      "control": "NetworkSeatDeclineApplicant@Leaver",
      "equals": {
        "pushed": true
      }
    },
    {
      "op": "mouse_up",
      "control": "NetworkSeatDeclineApplicant@Leaver"
    },
    {
      "op": "wait",
      "renders": 4
    },
    {
      "op": "assert_control",
      "control": "NetworkSeatDeclineApplicant@Leaver",
      "text_contains": "Confirm: decline"
    },
    {
      "op": "mouse_down",
      "control": "NetworkSeatDeclineApplicant@Leaver"
    },
    {
      "op": "wait",
      "control": "NetworkSeatDeclineApplicant@Leaver",
      "equals": {
        "pushed": true
      }
    },
    {
      "op": "mouse_up",
      "control": "NetworkSeatDeclineApplicant@Leaver"
    },
    {
      "op": "wait",
      "renders": 4
    },
    {
      "op": "menu",
      "command": "video_mark declined-host",
      "capture_screen": "game"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "declined-host",
      "scope": "menu"
    },
    {
      "op": "wait_file",
      "path": "{PROBE_DIR_newcomer}/declined.json",
      "within_ms": 120000
    },
    {
      "op": "wait",
      "control": "NetworkSeatApplicant@Leaver",
      "text_contains": "Newcomer",
      "equals": {
        "visible": true
      },
      "within_ms": 180000
    },
    {
      "op": "mouse_down",
      "control": "NetworkSeatApplicant@Leaver",
      "item": 0
    },
    {
      "op": "wait",
      "control": "NetworkSeatApplicant@Leaver",
      "equals": {
        "selected": 0
      }
    },
    {
      "op": "mouse_up",
      "control": "NetworkSeatApplicant@Leaver",
      "item": 0
    },
    {
      "op": "wait",
      "renders": 4
    },
    {
      "op": "assert_control",
      "control": "NetworkSeatSubstitute@Leaver",
      "equals": {
        "enabled": true
      },
      "text_contains": "Let Newcomer join"
    },
    {
      "op": "mouse_down",
      "control": "NetworkSeatSubstitute@Leaver"
    },
    {
      "op": "wait",
      "control": "NetworkSeatSubstitute@Leaver",
      "equals": {
        "pushed": true
      }
    },
    {
      "op": "mouse_up",
      "control": "NetworkSeatSubstitute@Leaver"
    },
    {
      "op": "wait",
      "renders": 4
    },
    {
      "op": "assert_control",
      "control": "NetworkSeatSubstitute@Leaver",
      "text_contains": "Confirm: let Newcomer join"
    },
    {
      "op": "mouse_down",
      "control": "NetworkSeatSubstitute@Leaver"
    },
    {
      "op": "wait",
      "control": "NetworkSeatSubstitute@Leaver",
      "equals": {
        "pushed": true
      }
    },
    {
      "op": "mouse_up",
      "control": "NetworkSeatSubstitute@Leaver"
    },
    {
      "op": "wait",
      "renders": 4
    },
    {
      "op": "menu",
      "command": "video_mark newcomer-let-in-host",
      "capture_screen": "game"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "newcomer-let-in-host",
      "scope": "menu"
    },
    {
      "op": "key_down",
      "key": "F6"
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "key_up",
      "key": "F6"
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "panel_open": false
    },
    {
      "op": "wait",
      "ai_held_peer_ids": [],
      "within_ms": 180000
    },
    {
      "op": "wait",
      "sim_advanced": 600,
      "within_ms": 120000
    },
    {
      "op": "menu",
      "command": "video_mark newcomer-playing-host",
      "capture_screen": "game"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "newcomer-playing-host",
      "scope": "menu"
    },
    {
      "op": "assert",
      "equals": {
        "service": "Running",
        "local_actor_alive": true
      }
    },
    {
      "op": "assert_relay"
    },
    {
      "op": "key_down",
      "key": "Escape"
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "key_up",
      "key": "Escape"
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "screen": "Pause"
    },
    {
      "op": "menu",
      "command": "activate ButtonEndMatch"
    },
    {
      "op": "wait",
      "screen": "PauseLeaveConfirm"
    },
    {
      "op": "menu",
      "command": "activate ButtonLeaveConfirm"
    },
    {
      "op": "wait",
      "scope": "menu",
      "screen": "MultiplayerScreen",
      "control": "LabelMultiplayerStatus",
      "text_contains": "Waiting for Joiner to press Ready",
      "within_ms": 90000
    },
    {
      "op": "signal",
      "name": "done",
      "scope": "menu"
    },
    {
      "op": "finish"
    }
  ],
  "activate_phase": "Running",
  "sim_clock": "lockstep"
}

